insert into public.articles (id, slug, category, category_name, title, summary, content, image, tags, keywords, created_at, updated_at, updated)
values
(1788345499078, 'rabelle-s-curve', 'main', 'Lore พื้นฐาน', 'Rabelle''s Curve', 'มาตรฐานที่ใช้ในการประเมินกราฟคลื่นความถี่ ของ Resonator ตลอดจนการวิเคราะห์เสถียรภาพของพลัง Forte ในตัวบุคคล', 'Rabelle''s Curve คือระเบียบวิธีวิจัยรูปแบบทางมาตรฐานที่ใช้ในการบันทึกและประเมินกราฟคลื่นความถี่ ของ Resonator... กราฟดังกล่าวทำหน้าที่แสดงอัตราการผันผวนของความถี่ ช่วยให้นักวิชาการและองค์กรวิจัยสามารถวิเคราะห์สภาวะทางกายภาพ ปรากฏการณ์การตื่นของพลัง ตลอดจนเสถียรภาพของพลัง Forte ในตัวบุคคลได้อย่างแม่นยำ
.
        ทฤษฎีและการทดสอบดังกล่าวถูกคิดค้นและพัฒนาขึ้นโดย Dr. Scott Rabelle... การทดสอบนี้ได้รับการยกย่องในวงการวิทยาศาสตร์อย่างกว้างขวางเนื่องจากมีความปลอดภัยสูง มีความน่าเชื่อถือ และสะดวกต่อการปฏิบัติงานในภาคสนาม... ทำให้ถูกนำไปปรับใช้เป็นมาตรฐานสากลในหลายภูมิภาคทั่ว Solaris... นอกจากนี้ อิทธิพลทางทฤษฎีของ Dr. Scott Rabelle ยังส่งผลให้มีการจัดตั้ง Rabelle College ขึ้นภายในสถาบัน Startorch ณ Lahai-Roi เพื่อทำหน้าที่ตรวจวิเคราะห์ จำแนก และฝึกอบรมเหล่า Synchronist ด้วยกระบวนการทางข้อมูลที่เข้มงวด
.
        ข้อมูลการวิเคราะห์ Rabelle''s Curve จะถูกระบุไว้อย่างเป็นระบบในเอกสาร "Character Forte Examination Report" ซึ่งเป็นเอกสารสำคัญทางเทคนิคที่แบ่งออกเป็นสองส่วนหลัก เพื่อใช้ประเมิน Resonator ทั้งในเชิงชีวภาพและพฤติกรรมความถี่ส่วนบุคคล... โดยแบ่งออกเป็น
    - Resonance Evaluation Report... ซึ่งมุ่งเน้นการตรวจสอบที่มาของการตื่นของพลัง ตำแหน่งของ Tacet Mark การเปลี่ยนแปลงทางกายภาพหลังการตื่นรู้ และระดับความสอดคล้องของ Resonance Spectrum Pattern กับวัตถุหรือปรากฏการณ์ธรรมชาติในโลก... ข้อมูล Rabelle''s Curve ในส่วนนี้จะถูกใช้เป็นดรรชนีหลักในการจัดประเภทของผู้สอดประสานออกเป็นประเภทต่างๆ
    - Overclock Diagnostic Report... ซึ่งทำหน้าที่วิเคราะห์ลักษณะคลื่นความถี่ Resonant Criticality และประวัติการสูญเสียการควบคุมพลัง ตลอดจนการประเมินความเสี่ยงต่อการเกิดสภาวะ Overclocking ซึ่งเป็นสภาวะอันตรายที่เกิดจากการที่สภาวะจิตใจของ Resonator ถูกกดดันจนพลังงาน Resonance ล้นทะลักและไม่สามารถควบคุมได้
.
        คุณลักษณะที่สำคัญของ Rabelle''s Curve ใน Resonator เกือบทุกประเภท คือการเป็นกราฟรูปคลื่นแบบ "ไร้จุดลู่เข้า" (Non-convergent Curve)... ลักษณะดังกล่าวชี้ให้เห็นว่าความถี่ของ Resonator ไม่ได้มีขีดจำกัดคงที่เหมือนวัตถุทั่วไป... แต่เป็นระบบเปิดที่มีศักยภาพในการขยายตัวและผันผวนตามปัจจัยกระตุ้น... จากทฤษฎีของDr. Scott Rabelle Resonator สามารถจำแนกออกเป็น 4 ประเภทหลักตามรูปแบบของเส้นโค้งและกลไกการตื่นรู้ของพลัง
        • Natural - กราฟไต่ระดับขึ้นอย่างค่อยเป็นค่อยไปและสม่ำเสมอ
        • Mutant - กราฟพุ่งสูงขึ้นอย่างชันกะทันหันในช่วงกลาง
        • Congenital - รูปแบบกราฟคลื่นเป็นคาบประจำอย่างต่อเนื่อง
        • Artificial - รูปแบบกราฟคลื่นมีรอยต่อของการสั่นพ้อง หรือมีความผิดปกติในโครงสร้าง
.
        ใน Natural Resonator แสดงให้เห็นถึงเส้นโค้งที่มีการเติบโตอย่างราบเรียบ... ผลการวิเคราะห์ Rabelle''s Curve ระบุถึงการเพิ่มขึ้นของระดับพลังอย่างมั่นคงพร้อมการผันผวนชั่วคราวที่อยู่ในเกณฑ์ปกติ ซึ่งอาจจะมีความเสี่ยง Overclock ในเฉพาะรายบุคคล
.
        ตรงกันข้ามกับกลุ่ม Mutant Resonator ซึ่งเส้นโค้งจะแฝงตัวในช่วงแรก ก่อนจะพุ่งชันขึ้นเป็นแนวตั้งเมื่อถูกกระตุ้นอย่างรุนแรง... โดยรายงานระบุว่ากราฟของ Resonator ประเภทนี้ไต่ระดับอย่างช้าๆ ในระยะแรก แล้วจึงพุ่งขึ้นอย่างกะทันหันในระยะต่อมา แม้กราฟจะพุ่งขึ้นอย่างกระทันหัน แต่ก็ไม่ใช่ Resonator ทุกคนที่จะมีความเสี่ยง Overclock สูง
.
        สำหรับกลุ่ม Congenital Resonator คลื่นสัญญาณแบบเป็นคาบประจำ... เป็นดรรชนีชี้วัดว่าโครงสร้างทางชีวภาพของ Resonator หลอมรวมกับความถี่ธรรมชาติมาตั้งแต่แรกเกิด ซึ่งสามารถควบคุมพลัง Forte ได้อย่างยั่งยืนเนื่องจากร่างกายมีความคุ้นเคยกับความถี่ระดับสูงมาแต่กำเนิด
.
        Artificial Resonator เส้นโค้งจะแสดงร่องรอยของการตัดต่อ Resonance หรือความบกพร่องของโครงสร้างคลื่น เป็นลักษณะเส้นโค้งที่ไม่เข้ากับฐานข้อมูลปกติ... Camellya ภูกจัดอยู่ในหมวดนี้เพื่อการเฝ้าระวัง เนื่องจากไม่มีข้อมูลการตื่นขึ้นของพลัง Resonance ที่ชัดเจน
.
        นอกจากนี้ยังมี Resonator อย่าง Lupa ที่ไม่ใช่ Mutant และไม่มีข้อมูลระบุชัดเจนว่าเป็น Congenital จึงถูกจัดอยู่ในหมวดหมูพิเศษอย่าง Non-Congenital Resonator... รวมไปถึง Resonator บางคนที่เอกสารไม่มีการระบุประเภทชัดเจนได้แค่ Hiyuki, Lucilla, Cantarella, Ciaccona, Luuk Herssen, Phoebe และ Qiuyuan
.
        รูปคลื่นของ Rabelle''s Curve เป็นเครื่องมือสำคัญที่นักวิจัยใช้ประเมินเสถียรภาพทางอารมณ์และขีดจำกัดของ Resonator... การประเมินสภาวะเสถียรภาพสูงปรากฏในกรณีของ Yangyang ซึ่งมีรูปคลื่นเป็นวงรีราบเรียบและมีค่า Resonant Criticality ต่ำมาก... แม้ในอดีตเธอจะเคยเผชิญสภาวะ Overclocking ระดับจากภาวะข้อมูลอารมณ์ล้นเกินจนทำให้ปลายเส้นผมเปลี่ยนรูปเป็นขนนกอย่างถาวร... แต่สภาวะโดยรวมยังคงได้รับการจัดการให้อยู่ในเกณฑ์ปลอดภัย ในเคสของ Lingyang แม้จะมีระดับ Resonant Criticality สูง แต่คลื่นวงรีที่สม่ำเสมอ ส่งผลให้ความเสี่ยงการเกิด Overclocking ของเขายังคงต่ำมาก
.
        ในทางกลับกัน การวิเคราะห์สภาวะความเสี่ยงสูงอย่างกรณีของ Calcharo พบว่ากราฟคลื่นแสดงลักษณะฟันปลาที่ไม่มีความเป็นระเบียบ... โดยมีค่าพีคเข้าใกล้ระดับวิกฤตตลอดเวลา รายงานประเมินชี้ว่า Calcharo มีความเสี่ยง Overclocking สูงมาก และเคยเข้าสู่สภาวะ Overclocking ระดับรุนแรง... ซึ่งส่งผลให้เกิดการกัดกร่อนจาก Tacet Discord การขยายตัวของหนามเงา และการปรากฏตัวของร่างอวตารสามร่าง
.
        นอกเหนือจากการประเมินทางชีวภาพ... Rabelle''s Curve ยังถูกนำมาใช้ในกระบวนการทดสอบความเข้ากันได้ของ Synchronist Test เพื่อยืนยันความสามารถของ Resonator ในการควบคุม Exostrider โดยระบบจะทำการจับคู่เปรียบเทียบเส้นโค้งของผู้ทดสอบกับค่ามาตรฐาน เพื่อรับรองว่า Resonator คนนั้นมีความถี่ที่เสถียรพอในการควบคุมโดยไม่เกิดสภาวะที่เป็นอันตราย', '/image/cover/cover_1788345496091.jpg', array['Rabelle''s Curve']::text[], null, '2/9/2569', '2/9/2569', 'เพิ่งสร้าง'),
(1788258145297, 'mt-firmament', 'regions', 'ภูมิภาค', 'Mt. Firmament', 'ครั้งอดีตกาลเมื่อ Jué ได้ปรากฏตัวครั้งแรกบน Mt. Firmament... ทิ้งร่องรอยเป็นวงแหวนขนาดยักษ์ที่ไม่อาจเข้าใจความหมายได้', '        Firmament มาจากภาษาละตินว่า Firmamentum ซึ่งมีความหมายว่า “สิ่งที่ค้ำจุน" หรือ "โครงสร้างที่มั่นคง”... อีกทั้งในบริบทดาราศาสตร์และคัมภีร์โบราณ Firmament ยังหมายถึง “พื้นฟ้าหรือโดมท้องฟ้าที่เชื่อว่าค้ำจุนสวรรค์และดวงดาว” อีกด้วย
.
        แต่เมื่อเราดูชื่อภาษาจีนของ Mt. Firmament หรือ 乘霄山 จะสามารถถอดความหมายได้ทีละตัวอักษรดังนี้
    - 乘 (เฉิง): หมายถึงการขับขี่, การโดยสาร, การเหยียบขึ้นไป, การทะยาน หรือการอาศัยจังหวะมวลลม... ในบริบทวรรณกรรมโบราณมักใช้กับการเคลื่อนที่ของเทพยดาหรือสิ่งศักดิ์สิทธิ์
    - 霄 (เซียว): หมายถึงชั้นฟ้าอันสูงส่ง, หาวหน, สรวงสวรรค์ หรือหมู่เมฆระดับสูง...
    - 山 (ซาน): หมายถึงภูเขาหรือเทือกเขา
ในตำนานจีนโบราณ ดินแดนของเหล่าเซียนหรือผู้บำเพ็ญพรตมักถูกพรรณนาว่าเป็นภูเขาที่ตัดขาดจากความวุ่นวาย ความเสื่อมถอย และกาลเวลาของโลกมนุษย์...
.
        ทัศนียภาพของ Mt. Firmament เป็นการผสมผสานระหว่างเทือกเขาสูงชัน ยอดเขาหิมะขาว ป่าไม้ใบสีแดงสด และบ่อน้ำพุร้อนธรรมชาติ โดยบ่อน้ำพุร้อนซึ่งเป็นแหล่งน้ำพุร้อนสีแร่ชาดธรรมชาติที่มีสรรพคุณในการฟื้นฟูสรีระ ลดความล้า และปรับสมดุลความถี่คลื่นพลังงานของ Resonator... บ่อน้ำพุร้อนแห่งนี้เกิดจากสายน้ำตก Snowy Stream ที่ไหลผ่านร่องหินและรากไม้ซีดาร์โบราณที่บรรพบุรุษปลูกไว้ กลายเป็นทั้งศูนย์กลางทางสันทนาการของชาวเมือง และแหล่งทรัพยากรธรรมชาติที่หล่อเลี้ยงระบบนิเวศบนเกาะมานานนับร้อยปี
.
        ความสันโดษของ Mt. Firmament ทำให้เกิดระบบนิเวศและชุมชนที่เป็นเอกลักษณ์เฉพาะตัว ชุมชนหลักบนเกาะคือเมืองโบราณ "Hongzhen" ซึ่งบริหารจัดการตนเองอย่างเป็นเอกเทศโดยตัดขาดจากโลกภายนอก... ชาวเมือง Hongzhen มีวัฒนธรรมโบราณที่สืบทอดกันมา เช่น การแสดงละครเงาฉากน้ำ การนำใบไม้แดงมาฉลุเป็นลายภาพ การต้มชาผลไม้ด้วยไม้ซีดาร์ และการอนุรักษ์ดอก Water Plums ในภาชนะบรรจุน้ำพุร้อน... ความเงียบสงบอันยาวนานนี้เป็นผลมาจากเขตอำนาจพิเศษที่แผ่ครอบคลุมทั้งเกาะ ซึ่งเป็นทั้งปราการคุ้มกันภัยและกรงขังมิติเวลาในเวลาเดียวกัน
.
        Mt. Firmament เคยได้รับผลกระทบจาก Temporal Barrier ซึ่งทำให้การไหลของเวลาผิดปกติ การออกจากภูเขาจะทำให้อายุขัยของผู้ที่อาศัยอยู่ภายใน สั้นลงอย่างทวีคูณ และยิ่งอยู่ใน Temporal Barrier นานเท่าไร โอกาสที่จะรอดชีวิตหลังออกไปก็ยิ่งน้อยลง... นี่จึงเป็นเหตุผลที่ชาว Hongzhen ส่วนใหญ่เลือกใช้ชีวิตอยู่ที่นี่ตลอดไป
.
        เชื่อกันว่า Jué มาจากดวงดาวอันห่างไกล และสถานที่แห่งนี้คือห้องจำศีล ขณะเดียวกันนักวิจัยจาก Court of Savantae ได้เดินทางมาศึกษาความผิดปกติของเวลา และสร้างระบบป้องกันให้ Mianloong Chamber เพื่อแลกกับโอกาสในการวิจัย จนกระทั่งกลุ่มคนที่ยังมีอายุน้อยพอจะทนต่อผลของการเร่งวัย(หนึ่งในนั้นคือ Rover) สามารถออกจาก Mt. Firmament ช่วยสงคราม ณ เมืองเยวียนและหุบเขาแห่งวิญญาณ จากนั้นก่อตั้ง Jinzhou ขึ้น... ส่วนผู้ที่เหลือเลือกอยู่ต่อ บูชา Jué ในฐานะเทพเจ้า ปฏิญาณว่าจะปกป้องผืนดิน และแกะสลักรูปลักษณ์ของ Sentinel ไว้บนภูเขา
.
        แม้ Mt. Firmament จะเคยเป็นดินแดนที่เคยมีปรากฏการณ์การไหลของเวลาที่ช้าลง แต่หลังจากปรากฏการณ์นี้ถูกแก้ไข พื้นที่อย่าง Hongzhen และโรงแรมบ่อน้ำพุร้อนเก่าแก่ Spring''s Taste จึงกลับมาเปิดรับผู้คนจากภายนอกอีกครั้ง... ที่นี่โดดเด่นด้วยบรรยากาศหิมะ ไอน้ำ และทิวทัศน์ภูเขา จนผู้มาเยือนรู้สึกราวกับได้เห็น “ดินแดนแห่งสวรรค์” อีกทั้งยังมีวัฒนธรรมอาหารเฉพาะตัวอย่างการปรุงอาหารด้วยน้ำพุร้อนและการแข่งขันไข่ออนเซ็นประจำปี ทำให้ Mt. Firmament ถูกนำเสนอในฐานะดินแดนที่ผสมผสาน ธรรมชาติ ความสงบ และบรรยากาศเหนือโลก เข้าด้วยกันอย่างชัดเจน
.
        Snowy Stream ธารน้ำท่ามกลางหิมะ ซึ่งเป็นต้นกำเนิดของระบบบ่อน้ำพุร้อนใน Hongzhen โดยมีต้นไม้เก่าแก่ที่ผู้ตั้งถิ่นฐานกลุ่มแรกปลูกไว้คอยโอบรับสายน้ำตกจากหน้าผา และเติบโตขึ้นจากรอยแยกของหินจนกลายเป็นต้นไม้ใหญ่ ผู้คนใน Hongzhen ยุคปัจจุบันได้ปรับแต่งภูมิทัศน์ให้สอดคล้องกับตำนานของ Snowy Stream ซึ่งเล่าว่าเมื่อหลายศตวรรษก่อน บุคคลลึกลับผู้หนึ่งเดินทางผ่านพื้นที่ในช่วงที่หิมะตกหนักจนปิดกั้นเส้นทางภูเขา เมื่อเห็นเสบียงฟืนของชาวบ้านกำลังร่อยหรอ บุคคลนั้นจึงใช้ พลัง Resonance เจาะเปิดทางผ่านภูเขาและเบี่ยงกระแสน้ำลงสู่หมู่บ้าน ทำให้หมอกและน้ำแข็งที่ละลายไหลไปทางตะวันตกพร้อมกับสายน้ำ เกิดเป็นภาพงดงามราวกับเซียนล่องลอยอยู่บนผิวน้ำ
.
• ลำดับเหตุการณ์สำคัญทางประวัติศาสตร์
    - Sentinel Jué เดินทางมาถึง Solaris-3 พร้อมกับ Mianloong Chamber โดยการขนส่งของ Exostrider
    - Court of Savantae เดินทางมาสร้าง Truthseeker''s Pass เพื่อศึกษาสัจธรรมแห่งเวลา
    - เกิด Tacet Discord ระบาดหนัก Jué กาง Temporal Barrier ชะลอเวลาบนเกาะ
    - คนกลุ่มหนึ่งเลือกที่จะออกจาก Mt. Firmament รวมถึง Rover ที่ออกมาพร้อมกับ Jué และช่วยเหลือสงคราม ณ เมืองเยวียนและหุบเขาแห่งวิญญาณ
    - Jué โอบอุ้มร่างทารกที่สิ้นชีพมายังเกาะ(Jinhsi) ใช้พลังเวลาชุบชีวิตและถ่ายพลังของตนเอง
    - เหตุการณ์ในบทที่ 1 ตอนที่ 7
.
• เขตพื้นที่ต่างๆ
    - Hongzhen เมืองที่พึ่งพาตนเองได้และตัดขาดจากโลกภายนอก อาคารที่เรียบหรูและสง่างามตั้งเรียงรายอยู่ตามท้องถนน ใบไม้สีแดงและหิมะสีขาวช่วยเสริมความงามอันเงียบสงบของเมืองนี้
    - Loong''s Crest เดิมทีชื่อว่า Empyrean Cliff ซึ่งตั้งอยู่บน Mt. Firmament... เพื่อเป็นการเฉลิมฉลองพรของ Jué ชาวบ้านบน Mt. Firmament ได้แกะสลักยอดแหลมตรงกลางของหน้าผาเป็นรูปปั้นของ Jué หลังจากนั้น Empyrean Cliff จึงเปลี่ยนชื่อเป็น Loong''s Crest
    - Loong''s Rest พื้นที่อันเงียบสงบของ Jué ท่ามกลางลมพายุที่โหมกระหน่ำและหิมะที่ปกคลุมตลอดทั้งปี แทบไม่มีร่องรอยของมนุษย์หลงเหลืออยู่เลย มีข่าวลือว่ามีสิ่งกีดขวางอันแข็งแกร่งคอยขัดขวางผู้ที่กล้าล่วงล้ำเข้ามาในอาณาเขตนี้
    - Loong''s Ridge ทางทิศใต้ของ Mt. Firmament เรียงรายไปด้วยเทือกเขาสูงตระหง่าน ทอดตัวเป็นเส้นทางคดเคี้ยวคล้ายกับลำตัวของลิง จึงเป็นที่มาของชื่อนี้ แม้ว่าจะมียอดเขาสูงชันอันตรายยื่นออกมาตามแนวสันเขา Loong''s Ridge แต่ที่นี่ก็เป็นที่อยู่อาศัยของสิ่งมีชีวิตหลากหลายชนิดในเขต Tundra
    - Luminous Shore เรือลำนั้นซึ่งบรรทุกผืนชายฝั่งอันกว้างใหญ่ไพศาลตั้งอยู่บนมุมหนึ่งของ Mt. Firmament มันตั้งตระหง่านอยู่บนสันเขาอันไร้ที่สิ้นสุดของ Mt. Firmament ต้อนรับนักเดินทางผู้เร่ร่อนจากอีกฟากหนึ่งของทะเลหมอก
    - Mianloong Chamber สถานที่พักผ่อนและหลีกหนีความวุ่นวายของ Jué และเป็นต้นกำเนิดของเมือง Jinzhou ทั้งหมด ตำนานเล่าว่ามันตกลงมาจากท้องฟ้า โดยมีผู้พิทักษ์อยู่ภายใน
    - Tianqu Tree ภายใต้ร่มเงาอันสูงตระหง่านของ Tianqu Tree ใบเมเปิลนับไม่ถ้วนประดับประดาผิวน้ำในสระ ตามตำนานเล่าว่า ใบไม้ที่ร่วงหล่นเหล่านี้จะกลับคืนสู่กิ่งก้านของต้นไม้ในสักวันหนึ่ง
    - Truthseeker''s Pass ซากปรักหักพังของ Court of Savantae ตั้งอยู่มุมเปลี่ยวในโลกที่ซ่อนเร้น
    - Woodveil Hall ถ้ำโบราณที่ซ่อนความลับที่ถูกปกปิดมานาน
    - Xuanji Ridges เมื่อ Jué ปรากฏตัวครั้งแรกบน Mt. Firmament ได้ทิ้งร่องรอยเป็นวงแหวนขนาดยักษ์และแปลกประหลาดกระจายอยู่ตามหน้าผาสูงตระหง่าน ไม่มีใครสามารถรับรู้ความหมายของวงแหวนเหล่านั้นได้ นอกจาก Jué เอง ', '/image/cover/cover_1788258142381.jpg', array['Mt. Firmament']::text[], null, '1/9/2569', '1/9/2569', 'เพิ่งสร้าง'),
(1788164890476, 'ซานเจย---ตรภพ', 'other', 'อื่นๆ', 'ซานเจี้ย - ตรีภพ', 'มนุษย์ผู้ซึ่งพยายามก้าวข้ามขอบเขตของตัวเอง... จึงพบกับสิ่งที่มีอำนาจเหนือความเข้าใจของตน', '        "ซานเจี้ย" (三界) หรือ ตรีภพ ตามคติเต๋าโดยแบ่งออกเป็น แดนมนุษย์ แดนพิภพ และแดนสวรรค์... ซึ่งทำหน้าที่เป็นระนาบการดำรงอยู่ของสัจธรรม กายเนื้อ และจิตวิญญาณตามลำดับตามระบบ ฟ้า ดิน และมนุษย์... หากเราลองทำความเข้าใจแล้วมองเนื้อเรื่องบทล่าสุดในอีกมุมมองหนึ่ง... มันจะสะท้อนให้เห็นว่าตัว Rover และ Qingxiao เพียงแค่เดินตามเส้นทางที่ Muyu เป็นคนเริ่มต้นเองเท่านั้น... และนั่นคือจุดหมายของการหยิบยก "ซานเจี้ย" มาใช้สอดแทรกเรื่องราวของตัว Muyu เอง... 
.
• แดนมนุษย์ - 人境
        ขอบเขตแห่งชีวิตของมนุษย์ที่ดำรงอยู่ท่ามกลางความเปลี่ยนแปลงของโลก เป็นพื้นที่ที่มนุษย์มีทั้งความปรารถนา ความสัมพันธ์ การเลือก และการกระทำของตนเอง แต่ในขณะเดียวกันก็ยังอยู่ภายใต้ เต๋า และการเคลื่อนไหวของธรรมชาติ... มนุษย์จึงไม่ได้ถูกมองว่าแยกขาดจากจักรวาล หากแต่เป็นส่วนหนึ่งของกระแสเดียวกัน แนวคิดอย่าง ''ความกลมกลืนระหว่างมนุษย์และธรรมชาติ'' จึงเน้นการดำรงชีวิตให้สอดคล้องกับฟ้าและธรรมชาติ มากกว่าการพยายามเอาชนะหรือควบคุมมัน
- แดนมนุษย์ในที่นี้จึงเปรียบเสมือน "โลกในอุดมคติที่มนุษย์สร้างขึ้น" (มนุษย์สร้างโลกในอุดมคติ)
.
• แดนพิภพ - 地境 
        แดนพิภพ สัมพันธ์กับ ดิน/แผ่นดิน ซึ่งเป็นอีกหนึ่งองค์ประกอบของระบบฟ้า ดิน มนุษย์... ในคติเต๋า ดินเป็นรากฐานที่รองรับและหล่อเลี้ยงสรรพสิ่ง เป็นตัวแทนของโลกแห่งรูปธรรม กระบวนการธรรมชาติ และการเปลี่ยนแปลงที่เกิดขึ้นอย่างต่อเนื่อง... หาก “ฟ้า” แสดงถึงระเบียบที่อยู่เหนือมนุษย์ “ดิน” ก็คือสนามที่หลักนั้นปรากฏออกมาเป็นสรรพสิ่งจริงๆ แดนพิภพจึงหมายถึง ขอบเขตของโลกธรรมชาติและสรรพสิ่งที่ดำรงอยู่บนพื้นฐานของเต๋า
- แดนพิภพในที่นี้จึงเปรียบเสมือน "โลกที่เริ่มไม่เชื่อฟังมนุษย์อีกต่อไป" (สิ่งที่สร้างเริ่มกลายเป็นส่วนหนึ่งของโลก และหลุดจากการควบคุม)
.
• แดนสวรรค์ - 天境
        แดนสวรรค์ สัมพันธ์กับ ฟ้า ซึ่งในปรัชญาจีนโบราณไม่ได้หมายถึงสถานที่บนท้องฟ้าเพียงอย่างเดียว แต่สามารถหมายถึง ระเบียบหรือหลักการของจักรวาลที่อยู่เหนือความต้องการของปัจเจก... ในคติเต๋า “ฟ้า” เป็นส่วนหนึ่งของกระบวนการตามธรรมชาติของเต๋า และไม่ได้หมายถึงเทพเจ้าผู้ปกครองโลกแบบตรงไปตรงมา การเข้าถึงระดับของฟ้าจึงตีความเชิงปรัชญาได้ว่าเป็นการเข้าใกล้ความเข้าใจในเต๋าม และธรรมชาติของจักรวาลมากขึ้น... ไม่ใช่การ “ขึ้นสวรรค์” ทางกายภาพ
- แดนสวรรค์ในที่นี้จึงเปรียบเสมือน "โลกที่เหนือการควบคุมและความต้องการของมนุษย์" (ก้าวพ้นขอบเขตของมนุษย์)
.
        การเดินทางจากโลกที่มนุษย์สร้าง ไปสู่การเผชิญหน้ากับโลกตามครรลองของมัน และท้ายที่สุดคือการพบเจอสิ่งที่มนุษย์ไม่อาจทำความเข้าใจ... มันคือการเดินทางของตัวร้ายอย่าง Muyu เพื่อทำความเข้าใจว่าแท้จริงแล้ว Sentinel คืออะไร มีความสัมพันธ์กับโลกและมนุษย์อย่างไร และเหตุใดจึงสามารถอยู่เหนือกฎที่มนุษย์เข้าใจได้... เสมือนการค่อย ๆ ลอกชั้นของความจริงออกจากโลกที่มนุษย์สร้างขึ้น ไปสู่โลกที่ไม่อาจควบคุม และท้ายที่สุดคือการเผชิญหน้ากับความจริงของ “ฟ้า” ซึ่งเป็นสิ่งที่ Muyu เชื่อว่าควรถูกเปิดเผย... ซึ่งสุดท้ายก็ถูกยับยั้งเอาไว้ แม้ความจริงนั้นอาจจะเป็นประโยชน์หรืออาจขัดแย้งกับสิ่งที่มนุษย์เคยเชื่อเกี่ยวกับ Sentinel ก็ตาม', '/image/cover/cover_1788164887927.jpg', array['Muyu']::text[], null, '31/8/2569', '31/8/2569', 'เพิ่งสร้าง'),
(1788164776049, 'rover', 'other', 'อื่นๆ', 'ครั้งแรกของ Rover?', 'Rover เองยังไม่เคยได้รับพลังจาก Sentinel มาก่อน... จนกระทั่ง Hsin มอบพลังให้ผ่าน "ปริซึมแห่งโชคชะตา"', 'รู้หรือไม่? ตั้งแต่ Rover รีเซ็ตตัวตนของตนเองและเริ่มพเนจรใน Solaris-3 ครั้งล่าสุด... ตัว Rover เองยังไม่เคยได้รับพลังจาก Sentinel มาก่อนเลยจนกระทั่ง Hsin มอบพลัง Electro ให้ผ่าน "ปริซึมแห่งโชคชะตา"
.
        • Spectro Rover - แม้จะเป็น Spectro และมีความสามารถในการควบคุมเวลาแบบ Jue และ Jinhsi แต่แท้จริงแล้วพลัง Spectro ของ Rover นั้นเป็นพลังดั้งเดิมติดตัว Rover เองอยู่แล้ว ซึ่งมีความเป็นไปได้สูงว่าได้รับพลังนี้มาจาก Instance One(ควบคุมเวลา)... และ Jue ก็เป็นผู้ที่รับสืบทอดพลัง Spectro ของ Rover อีกที... ก่อนจะสั่นพ้องกับ Jinhsi และถ่ายโอนพลังโดยสมบูรณ์ในเนื้อเรื่องบทที่ 1 ตอนที่ 7 ของเวอร์ชั่น 1.1
.
        • Havoc Rover - ปัจจุบันยังไม่มีการยืนยันว่า Sentinel ตัวใดๆ มีความสามารถใช้แพลัง Havoc ได้... และพลัง Havoc นี้เองแท้จริงแล้วก็เป็นเศษเสี้ยวของ Ovathrax ที่มีความถี่ส่วนใหญ่เป็นของ Dreamless
.
        • Aero Rover - แม่ว่าพลังทุกอย่างของ Aero จะมีความสามารถคล้ายเคียงกับ Imperator แต่พลังที่ Rover ได้รับมานั้นคือการดูดซับความถี่ของ Cartethyia ไม่ใช่ตัว Imperator โดยตรง
.
และนั่นจึงทำให้...
        • Electro Rover - เป็นการรับพลังจาก Sentinel Hsin โดยตรง... แต่ตัว Rover นั้นไม่ได้สั่นพ้องกับ Hsin โดยตรงแต่เป็นการหยิบยืมพลังของ Hsin ที่บรรจุไว้ใน "ปริซึมแห่งโชคชะตา" ด้วยเหตุนี้ Electro Rover จึงยังไม่ใช่ Sentinel''s Resonator เหมือนกับ Jinhsi หรือ Aemeath... นั่นหมายความว่าในอนาคตอาจจะยังมีการเปิดเผยตัวละครที่เป็น Resonator ของ Hsin เองก็เป็นได้', '/image/cover/cover_1788164773543.jpg', array['Rover']::text[], null, '31/8/2569', '31/8/2569', 'เพิ่งสร้าง'),
